  return wrap("C20", "A light prefix can block the valuable singleton", "The legal density prefix gets 2; the singleton gets 19. The fractional remainder and prefix-plus-singleton bound explain the one-half choice.", <><Compare><div><Capacity title="Prefix A" items={items} capacity={10} amounts={[{ index: 0 }]} /><Capacity title="Fractional remainder 9/10 of B" items={items} capacity={10} amounts={[{ index: 0 }, { index: 1, fraction: 0.9 }]} /></div><div><Capacity title="Best feasible singleton B" items={items} capacity={10} amounts={[{ index: 1 }]} /></div></Compare><Ruler title="Benefit comparison" max={22} unit="benefit units" marks={[{ value: 2, label: "P" }, { value: 19, label: "V" }, { value: 19.1, label: "fractional" }, { value: 21, label: "P+V" }]} /><Table label="Filter before forming either answer" headers={["Empty/no-fitting input", "Selected answer", "Ratio"]} rows={[[true, "empty", "undefined when optimum zero"]]} /></>);
