function RecordedCoverDrawing({ state, title = "Actual 34-node, 78-tie support" }) {
  const nodes = state.nodes.map((v, i) => ({ x: 400 + 285 * Math.cos(2 * Math.PI * i / 34 - Math.PI / 2), y: 355 + 285 * Math.sin(2 * Math.PI * i / 34 - Math.PI / 2), label: String(v) }));
  return <><Graph title={title} nodes={nodes} edges={state.edges.map(([a, b], i) => ({ a, b, id: i }))} selectedNodes={state.selected} highlight={[state.edge]} width={800} height={710} /><Table tall label="Every recorded node: original paper mapping and decision value" headers={["Node ID", "Original paper ID", "Constructed unit cost", "Chosen x", "Incident dual load"]} rows={state.nodes.map((v) => [v, v + 1, 1, state.values[v], sum(state.edges.map(([a, b], i) => a === v || b === v ? state.edge_loads[i] : 0))])} /><Table tall label="Every recorded tie: LP inequality and independent dual load" headers={["Edge", "A", "B", "x_A+x_B", "LP dual y"]} rows={state.edges.map(([a, b], i) => [i, a, b, state.coverage[i], state.edge_loads[i]])} /></>;
}
